(4720, 889, 'desc', '<ul>\n 	<li>2 New York strip steaks</li>\n 	<li>1 onion, cut into thick circles or strips</li>\n 	<li>3 cloves garlic</li>\n 	<li>1 tablespoon butter</li>\n 	<li>1 teaspoon salt</li>\n 	<li>1 teaspoon fres.hly ground black pepper</li>\n 	<li>1 teaspoon ground cumin</li>\n 	<li>1 teaspoon ground coriander</li>\n 	<li>1 teaspoon papriks</li>\n</ul>'),
(4721, 889, 'ingre', '<div class=\"row\">\n<div class=\"col-md-6 col-sm-6 col-xs-12\">\n<ul>\n 	<li>cooking spray</li>\n 	<li>1/3 pound ground beef</li>\n 	<li>salt and ground black pepper to taste</li>\n 	<li>24 wonton wrappers</li>\n 	<li>1 3/4 cups grated Parmesan cheese</li>\n</ul>\n</div>\n<div class=\"col-md-6 col-sm-6 col-xs-12\">\n<ul>\n 	<li>3/4 cups shredded mozzarella cheese</li>\n 	<li>3/4 cup ricotta cheese</li>\n 	<li>3/4 cup ricotta cheese</li>\n 	<li>1/4 cup chopped fresh basil, or to taste (optional)</li>\n</ul>\n</div>\n</div>'),
