(39, 'woopay-beta-merchantrecruitment-short-06MAY23-TESTC', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(40, 'woopay-beta-merchantrecruitment-short-06MAY23-TESTD', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(41, 'woopay-beta-merchantrecruitment-short-09MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(42, 'woopay-beta-merchantrecruitment-short-update-09MAY23', 'info', 'en_US', 'Increase conversions with WooPay — our fastest checkout yet', 'Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(43, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'woo-activation-survey-blockers-22AUG23', 'info', 'en_US', 'How can we help you get that first sale?', 'Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!', '{}', 'unactioned', 'woocommerce.com', '2024-07-14 07:41:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2024-07-12 04:04:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(59, 'wc-admin-customizing-product-catalog', 'info', 'en_US', 'Cách tùy chỉnh danh mục sản phẩm của bạn', 'Bạn muốn danh mục sản phẩm và hình ảnh của mình trông đẹp mắt và phù hợp với thương hiệu của bạn. Hướng dẫn này sẽ cung cấp cho bạn tất cả các mẹo bạn cần để sản phẩm của bạn trông đẹp mắt trong cửa hàng của bạn.', '{}', 'unactioned', 'woocommerce-admin', '2024-07-14 07:41:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'wc-admin-mobile-app', 'info', 'en_US', 'Install Woo mobile app', 'Install the WooCommerce mobile app to manage orders, receive sales notifications, and view key metrics — wherever you are.', '{}', 'unactioned', 'woocommerce-admin', '2024-07-14 07:41:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(61, 'wc-admin-wc-helper-connection', 'info', 'en_US', 'Connect to WooCommerce.com', 'Connect to get important product notifications and updates.', '{}', 'unactioned', 'woocommerce-admin', '2024-07-15 07:54:30', NULL, 0, 'plain', '', 0, 0, 'info'),
(62, 'wc-admin-onboarding-payments-reminder', 'info', 'en_US', 'Bắt đầu chấp nhận thanh toán trên cửa hàng của bạn!', 'Nhận thanh toán với nhà cung cấp phù hợp với bạn - chọn từ hơn 100 cổng thanh toán cho WooCommerce.', '{}', 'unactioned', 'woocommerce-admin', '2024-07-17 04:05:16', NULL, 0, 'plain', '', 0, 0, 'info'),
(63, 'wc-admin-usage-tracking-opt-in', 'info', 'en_US', 'Hỗ trợ WooCommerce cải thiện với tính năng theo dõi sử dụng', 'Việc thu thập dữ liệu sử dụng cho phép chúng tôi cải thiện WooCommerce. Cửa hàng của bạn sẽ được xem xét khi chúng tôi đánh giá các tính năng mới, đánh giá chất lượng của bản cập nhật hoặc xác định xem một cải tiến có hợp lý hay không. Bạn luôn có thể truy cập <a href=\"https://tdhworld.com/wp-admin/admin.php?page=wc-settings&#038;tab=advanced&#038;section=woocommerce_com\" target=\"_blank\">Cài đặt</a> và chọn ngừng chia sẻ dữ liệu. <a href=\"https://woocommerce.com/usage-tracking?utm_medium=product\" target=\"_blank\">Đọc thêm</a> về dữ liệu chúng tôi thu thập.', '{}', 'unactioned', 'woocommerce-admin', '2024-07-19 04:04:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'klaviyo_q4_2024', 'marketing', 'en_US', 'Need a marketing solution to help you sell more?', 'Over 13,000 brands use Klaviyo to grow faster. You can drive 46x ROI with their personalized email, SMS, forms, and product reviews. Start for free today.', '{}', 'pending', 'woocommerce.com', '2024-08-01 04:21:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'wnww-recap-july', 'marketing', 'en_US', 'Powerful updates and upgrades in WooCommerce', 'Have you seen all the latest from Woo? Check out our recent roundup for a look at the newest features, extensions, and insights making WooCommerce perform better than ever.', '{}', 'pending', 'woocommerce.com', '2024-08-14 04:10:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(66, 'bfcm2024-landing-page', 'marketing', 'en_US', 'The best way to prepare for holiday success', 'The upcoming holiday season is the busiest time of the year for many online stores. We want to help you make the most of it with an early gift: our first-ever Black Friday Cyber Monday Trends Report. It\'s full of stats, trends, and recommendations to knock your holiday socks off!', '{}', 'pending', 'woocommerce.com', '2024-09-05 04:07:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(67, 'stripe_securityupdate_q3_2024', 'update', 'en_US', 'Security update required for your Stripe extension', 'To continue securely accepting payments, you must update your Stripe extension to at least version 8.6, re-authenticate, and turn on the new checkout experience. Review the documentation for instructions on how to make the necessary changes from your WooCommerce dashboard.', '{}', 'pending', 'woocommerce.com', '2024-09-19 04:03:23', NULL, 0, 'plain', '', 0, 0, 'info'),
(68, 'paypal_migration_Q3_2024', 'marketing', 'en_US', 'You’re using an outdated version of PayPal', 'Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.', '{}', 'pending', 'woocommerce.com', '2024-10-04 04:33:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, 'wc-admin-real-time-order-alerts', 'info', 'en_US', 'Get real-time order alerts anywhere', 'Get notifications about store activity, including new orders and product reviews directly on your mobile devices with the Woo app.', '{}', 'unactioned', 'woocommerce-admin', '2024-10-10 05:24:04', NULL, 0, 'plain', '', 0, 0, 'info'),
(70, 'paypal_migration_Q3_2024_v2', 'marketing', 'en_US', 'You’re using an outdated version of PayPal', 'Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.', '{}', 'pending', 'woocommerce.com', '2024-10-31 04:39:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(71, 'mollie_q4_2024', 'marketing', 'en_US', 'Special offer: Zero transaction fees for your first month with Mollie', 'With seamless checkout, flexible financing, and 30+ local and global payment methods, Mollie is the all-in-one payment solution that enhances the customer experience and helps your business grow. Start your account today and enjoy ZERO transaction fees for the first month. Ts&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2024-11-01 04:08:16', NULL, 0, 'plain', '', 0, 0, 'info'),
(72, 'Renewal_notification_emails_Woosubscriptions_Nov2024', 'marketing', 'en_US', 'WooCommerce Subscriptions just got even better', 'You can now send automatic email reminders to customers before their subscriptions renew or expire. To enable this for your store, update to the latest version of WooCommerce Subscriptions (don\'t forget to make a backup first) and follow the steps linked below.', '{}', 'pending', 'woocommerce.com', '2024-11-19 04:11:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(73, 'paypal_promo_Q4_2024', 'marketing', 'en_US', 'Add PayPal to your existing checkout this holiday season', 'Drive conversion and give customers more confidence to buy when you complement your checkout with PayPal, Venmo, Pay Later, and more. Attract new shoppers and give them a streamlined buying experience with Fastlane, PayPal’s fast and simple guest checkout.', '{}', 'pending', 'woocommerce.com', '2024-11-28 04:03:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(74, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2024-12-04 04:04:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(75, 'usps-mail-service-to-canada-suspended-dec-2024', 'update', 'en_US', 'Please note: USPS Mail Service to Canada Suspended', 'The United States Postal Service has temporarily suspended mail service to Canada due to the ongoing Canadian postal workers\' strike. USPS is asking users to refrain from mailing items to Canada at this time.', '{}', 'pending', 'woocommerce.com', '2024-12-05 04:06:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(76, 'Announce-UPS-WCShipping-Dec2024', 'marketing', 'en_US', 'WooCommerce Shipping now supports select UPS services', 'Give customers the power and reliability of UPS, directly from your dashboard. Access discounted rates, convenient shipping options, and fast, on-time delivery with UPS on WooCommerce Shipping — and stay tuned for UPS® Ground Saver rates coming in 2025.', '{}', 'pending', 'woocommerce.com', '2024-12-13 04:45:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(77, 'account-creation-after-checkout-dec2024', 'marketing', 'en_US', 'Offer account creation after checkout', 'Your customers can now create accounts after they check out on block-based themes. Enable the new “After checkout” block in your account settings and enjoy smoother guest checkout, better conversion, and more repeat business.', '{}', 'pending', 'woocommerce.com', '2024-12-19 04:09:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(78, 'woocommerce-analytics-order-attribution-promotions-december-2024', 'marketing', 'en_US', 'Discover what drives your sales', 'Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.', '{}', 'pending', 'woocommerce.com', '2024-12-24 04:10:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(79, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Quản lý đơn hàng của bạn khi đang di chuyển', 'Tìm kiếm đơn đặt hàng, thông tin khách hàng và xử lý hoàn tiền chỉ bằng một cú nhấp chuột với ứng dụng Woo.', '{}', 'unactioned', 'woocommerce-admin', '2025-01-08 04:05:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(80, 'affirm_promo_Q1_2025', 'marketing', 'en_US', 'Save up to 50% on merchant fees with Affirm', 'Kickstart the year with buy now, pay later and get merchant rates as low as 2.9% + 30¢ per transaction for 30 days. Download the extension and complete your application from your WooCommerce dashboard by February 19, 2025 to claim the offer. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2025-01-21 04:11:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(81, 'new-woo-brand-announcement-feb4-2025', 'marketing', 'en_US', 'Meet the new Woo', 'WooCommerce has a new look, but underneath, we’re still the same customizable, open-source ecommerce platform you know and love. Plus, we’ve got some major improvements to our platform and product on the way.', '{}', 'pending', 'woocommerce.com', '2025-02-05 04:11:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(82, 'paypal_bnpl_au_promo_Q1_2025', 'marketing', 'en_US', 'Australian shoppers can Pay in 4 with PayPal', 'Enable Pay in 4 messaging to let Australian customers know that they can pay over time while you get paid up front and in full. Pay in 4 is included in PayPal Payments at no additional cost. Eligible buyers can pay in four interest-free payments for purchases of $30 to $2,000 AUD. Terms apply.', '{}', 'pending', 'woocommerce.com', '2025-02-12 04:34:22', NULL, 0, 'plain', '', 0, 0, 'info'),
(83, 'stripe_stripetax_q1_2025', 'marketing', 'en_US', 'Say goodbye to your tax woes', 'Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.', '{}', 'pending', 'woocommerce.com', '2025-02-20 04:05:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(84, 'printful_promo_q1_2025', 'marketing', 'en_US', 'New: sell print-on-demand products, risk-free', 'Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.', '{}', 'pending', 'woocommerce.com', '2025-02-26 04:15:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(85, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-03-04 04:06:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(86, 'woo-marketplace-two-year-subscriptions-rin-2025-03-17', 'marketing', 'en_US', 'Save 20% on new two-year subscriptions', 'We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.', '{}', 'pending', 'woocommerce.com', '2025-03-17 04:20:29', NULL, 0, 'plain', '', 0, 0, 'info'),
(87, 'viva_wallet_migration_q1_2025', 'update', 'en_US', 'Switch to the new Viva.com Smart Checkout', 'The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.', '{}', 'pending', 'woocommerce.com', '2025-04-04 04:35:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(88, 'stripe_orderstatus_bug_q2_2025', 'update', 'en_US', 'Action Required: Update Order Status Manager', 'Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.', '{}', 'pending', 'woocommerce.com', '2025-04-04 04:35:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(89, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Theo dõi hiệu suất cửa hàng của bạn trên thiết bị di động', 'Theo dõi doanh số và sản phẩm hoạt động hiệu quả cao của bạn bằng ứng dụng Woo.', '{}', 'unactioned', 'woocommerce-admin', '2025-04-08 04:03:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(90, 'WooCommerce-Stripe-Gateway-Update-April-2025', 'update', 'en_US', 'Action required: Update WooCommerce Stripe Gateway to v9.4.1', '<strong>An important update for WooCommerce Stripe Payment Gateway has been released</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. Please update as soon as possible for optimal store performance. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-19 04:14:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(91, 'WooCommerce-Stripe-Gateway-Update-Info-April-2025', 'update', 'en_US', 'WooCommerce Stripe Gateway has been updated to v9.4.1', '<strong>WooCommerce Stripe Payment Gateway was recently updated</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. No further action is required. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory post </a>for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-19 04:14:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(92, 'klaviyo_q2_2025', 'marketing', 'en_US', 'Tailor your marketing with data-driven automation', 'Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity', '{}', 'pending', 'woocommerce.com', '2025-04-30 04:06:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(93, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-05-06 04:06:11', NULL, 0, 'plain', '', 0, 0, 'info'),
(94, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-05-13 04:13:49', NULL, 0, 'plain', '', 0, 0, 'info'),
(95, 'paypal_q2_2025', 'marketing', 'en_US', 'Power up sales with Pay Later messaging', 'Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.', '{}', 'pending', 'woocommerce.com', '2025-05-22 04:26:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(96, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-05-30 04:07:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(97, 'tento_q2_2025', 'marketing', 'en_US', 'Get your free business credit score', 'Strong business credit is the key to better deals, stronger partnerships, and sustainable growth. Tento Business Credit Monitoring helps you catch risks early, secure better financing, and fuel smarter growth — with no impact to your credit.', '{}', 'pending', 'woocommerce.com', '2025-06-04 04:18:21', NULL, 0, 'plain', '', 0, 0, 'info'),
(98, 'woopayments-multibanco-alipay-wechat-launch-2025-06-23', 'marketing', 'en_US', 'Multibanco, AliPay and WeChat now available in WooPayments', 'Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.', '{}', 'pending', 'woocommerce.com', '2025-06-24 04:07:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(99, 'woopayments-new-lpms-2025-06-30', 'marketing', 'en_US', 'Get the POS built specifically for Woo stores', 'Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required', '{}', 'pending', 'woocommerce.com', '2025-07-01 04:30:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(100, 'tiktok-webinar-promo-july2025', 'marketing', 'en_US', 'You\'re Invited: TikTok for WooCommerce Webinar', 'Join us for a free webinar with our friends at TikTok on Tuesday, July 8, at 4 pm UTC. We\'ll cover creative tips and best practices for making content that turns views into sales.', '{}', 'pending', 'woocommerce.com', '2025-07-01 04:30:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(101, 'wc-admin-email-improvements', 'info', 'en_US', 'Email cửa hàng đã được nâng cấp!', 'Chúng tôi đã thực hiện một số cải tiến thú vị cho các mẫu email, bao gồm các thiết kế hiện đại, thân thiện với người mua hàng và các tùy chọn tùy chỉnh mới. Và nếu bạn đang sử dụng giao diện khối, bạn có thể tự động đồng bộ hóa các kiểu giao diện của mình! Hãy truy cập cài đặt email để khám phá các tính năng mới.', '{}', 'unactioned', 'woocommerce-admin', '2025-07-02 04:03:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(102, 'woopayments-grabpay-launch-2025-07-07', 'marketing', 'en_US', 'GrabPay now available in WooPayments', 'Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.', '{}', 'pending', 'woocommerce.com', '2025-07-08 04:03:38', NULL, 0, 'plain', '', 0, 0, 'info'),
(103, 'wc-admin-edit-products-on-the-move', 'info', 'en_US', 'Chỉnh sửa sản phẩm khi di chuyển', 'Chỉnh sửa và tạo sản phẩm mới từ thiết bị di động của bạn bằng ứng dụng Woo', '{}', 'unactioned', 'woocommerce-admin', '2025-07-12 04:06:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(104, 'BFCM-25-Survey', 'marketing', 'en_US', 'You’re invited: Take our quick BFCM survey and get 25% off', 'We’re gathering insights on how businesses prepare for peak sales moments like Black Friday and Cyber Monday — so we can better support you. Take our quick 8-minute survey to share your thoughts and get 25% off your next WooCommerce extension as a thank you.', '{}', 'pending', 'woocommerce.com', '2025-07-15 04:05:54', NULL, 0, 'plain', '', 0, 0, 'info'),
(105, 'woohoo10-coupon', 'marketing', 'en_US', 'Celebrate and save with WooCommerce 10.0', 'To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.', '{}', 'unactioned', 'woocommerce.com', '2025-07-22 04:08:54', NULL, 0, 'plain', '', 0, 0, 'info'),
(106, 'paypaladvantage_q3_2025', 'marketing', 'en_US', 'Add PayPal Checkout and earn up to $1,000*', 'PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*', '{}', 'pending', 'woocommerce.com', '2025-07-23 04:03:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(107, 'stripe_optimizedcheckout_upgrade_q3_2025', 'marketing', 'en_US', 'Upgrade for a faster, more flexible Stripe checkout', 'You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-14 04:16:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(108, 'stripe_optimizedcheckout_enable_q3_2025', 'marketing', 'en_US', 'Unlock dynamic payments and sell more', 'You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.', '{}', 'pending', 'woocommerce.com', '2025-08-14 04:16:46', NULL, 0, 'plain', '', 0, 0, 'info');
INSERT INTO `wp_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(109, 'stripe_optimizedcheckout_promotion_q3_2025', 'marketing', 'en_US', 'Upgrade to Stripe for a faster, more flexible checkout', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-16 04:44:52', NULL, 0, 'plain', '', 0, 0, 'info'),
(110, 'woo-subscription-gifting-bundling-2025-08-18', 'marketing', 'en_US', 'Grow recurring revenue with gifting', 'WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.', '{}', 'pending', 'woocommerce.com', '2025-08-20 09:21:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(111, 'stripe_optimizedcheckout_competitors_q3_2025', 'marketing', 'en_US', 'Upgrade to the official WooCommerce Stripe Payment Gateway', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.', '{}', 'pending', 'woocommerce.com', '2025-08-29 04:27:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(112, 'UPS-promo-RIN-WCS-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-11 04:50:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(113, 'UPS-promo-RIN-WCST-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-11 04:50:19', NULL, 0, 'plain', '', 0, 0, 'info'),
(114, 'square_ordersync_upgrade_q3_2025', 'marketing', 'en_US', 'You asked, we delivered — order sync is here for Square', 'Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.', '{}', 'pending', 'woocommerce.com', '2025-09-12 04:12:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(115, 'klaviyo_q3_2025', 'marketing', 'en_US', 'Smarter marketing starts with Woo x Klaviyo', 'Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.', '{}', 'pending', 'woocommerce.com', '2025-09-17 04:05:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(116, 'pinterest_q3_20252', 'marketing', 'en_US', 'More visibility, smarter campaigns', 'Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.', '{}', 'pending', 'woocommerce.com', '2025-09-24 04:04:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(117, 'pinterest_q4_2025', 'marketing', 'en_US', 'Maximize conversions with Pinterest', 'Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.', '{}', 'pending', 'woocommerce.com', '2025-10-22 04:06:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(118, 'paypaladvantage_q4_2025', 'marketing', 'en_US', 'PayPal Checkout offer: Get 40% back on fees for 3 months', 'Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.', '{}', 'pending', 'woocommerce.com', '2025-11-05 04:19:16', NULL, 0, 'plain', '', 0, 0, 'info'),
(119, 'reddit_q4_2025', 'marketing', 'en_US', 'New: Reach high-intent shoppers on Reddit', 'Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.', '{}', 'pending', 'woocommerce.com', '2025-11-14 04:06:25', NULL, 0, 'plain', '', 0, 0, 'info'),
(120, 'bfcm_general_sale_q4_2025', 'marketing', 'en_US', 'Save up to 40% on extensions and themes', 'For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.', '{}', 'pending', 'woocommerce.com', '2025-11-20 04:07:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(121, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'pending', 'woocommerce.com', '2025-12-04 04:36:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(122, 'Googleupdate_q4_2025', 'marketing', 'en_US', 'Make every ad dollar count this holiday season', 'Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.', '{}', 'pending', 'woocommerce.com', '2025-12-05 04:05:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(123, 'holiday_shipping_deadlines_WCST_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 04:21:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(124, 'holiday_shipping_deadlines_WCS_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-12 04:21:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(125, 'snap_q4_2025', 'marketing', 'en_US', 'New: Reach a new audience on Snapchat', '88% of Snapchatters love to shop, and 40% aren\'t active on other social platforms. Connect with them and grow your business using Snapchat for WooCommerce, our new official extension. Sync your products, launch ad campaigns, and track results — all from your Woo dashboard.', '{}', 'pending', 'woocommerce.com', '2025-12-19 05:18:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(126, 'stripe_agenticcommerce_3PDS_q4_2025', 'marketing', 'en_US', 'Get more from Stripe with the official extension', 'Switch to the official extension co-developed with Stripe for the latest features and best performance. Get access to personalized checkout options, early support for AI shopping through Stripe’s <a href=\"https://woocommerce.com/posts/stripe-agentic-commerce-suite-for-woocommerce/\">Agentic Commerce Suite</a>, and more.', '{}', 'pending', 'woocommerce.com', '2025-12-19 05:18:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(127, 'WC10.4.3-security-update-12-22-2025', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-12-23 08:58:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(128, 'downloads-sub-Jan2026-RIN', 'marketing', 'en_US', 'WooCommerce Subscription Downloads is now part of WooCommerce Subscriptions', 'WooCommerce Subscriptions now allows you to include simple and variable downloadable products with your subscriptions. Streamline your subscription downloads by updating to the latest version of WooCommerce Subscriptions today.', '{}', 'pending', 'woocommerce.com', '2026-01-08 07:28:14', NULL, 0, 'plain', '', 0, 0, 'info'),
(129, 'paypal-carding-recaptcha-jan-26', 'update', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'pending', 'woocommerce.com', '2026-01-13 04:46:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(130, 'USPS API Migration_RIN_Jan2026', 'marketing', 'en_US', 'Upgrade to USPS Shipping REST API by January 25', 'USPS is retiring the legacy Web Tools API on January 25, 2026. If you’re using the USPS Shipping Method extension with the legacy API, live USPS shipping rates will longer be shown at checkout. Migrate to the REST API now to avoid disruption.', '{}', 'pending', 'woocommerce.com', '2026-01-14 04:55:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(131, 'existing_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2026-01-23 06:38:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(132, 'prospects_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.', '{}', 'pending', 'woocommerce.com', '2026-01-23 06:38:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(133, 'reddit_q1_2026', 'marketing', 'en_US', 'Start advertising on Reddit with a $500 bonus', 'Make the most of our new Reddit integration with $500 in Reddit Ads! For a limited time, new advertisers who spend $500 in Reddit Ads Manager over 30 days will get $500 in ad credit. Your bonus credit unlocks automatically when you hit $500 in spend. Use your credit within 30 days.', '{}', 'pending', 'woocommerce.com', '2026-02-06 04:16:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(134, 'Googleupdate_q1_2026', 'marketing', 'en_US', 'Make every ad dollar count', 'Google for WooCommerce now includes Budget Recommendations. Promote your products across Google — from Search to YouTube and beyond — and get personalized suggestions on where to optimize campaign budgets to reach more shoppers.', '{}', 'pending', 'woocommerce.com', '2026-02-11 06:28:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(135, 'Mailchimp-API-maintenance-feb-2026', 'update', 'en_US', 'Mailchimp Maintenance Feb 28', 'Mailchimp will be carrying out planned API maintenance on February 28 from 11am – 4pm EST. During that time, you may see brief sync interruptions in Mailchimp for WooCommerce. Most data will catch up automatically. See the <a href=\"https://developer.woocommerce.com/2026/02/27/mailchimp-api-maintenance-february-28/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-02-27 04:26:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(136, 'RIN-WC-Security-Update-admin-update-March-2026', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'unactioned', 'woocommerce.com', '2026-03-03 04:04:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(137, 'USPS_Scan_Form_Mar2026', 'marketing', 'en_US', 'New: Save time shipping with USPS SCAN Form', 'USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.', '{}', 'pending', 'woocommerce.com', '2026-03-12 06:17:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(138, 'usps-surcharge-apr2026', 'marketing', 'en_US', 'Heads up: USPS rates increasing 8% on April 26', 'USPS is adding a temporary 8% surcharge on Priority Mail, Priority Mail Express, Ground Advantage, and Parcel Select from April 26, 2026 through January 17, 2027. WooCommerce Shipping discounted rates still apply.', '{}', 'pending', 'woocommerce.com', '2026-04-22 04:53:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(139, 'stripe-woo-gateway-update-april2026', 'update', 'en_US', 'A critical update is required for Stripe for WooCommerce', '<strong>A critical update is required for Stripe for WooCommerce</strong> that addresses possible payment issues. Please update the WooCommerce Stripe Gateway to v10.6.1 immediately.', '{}', 'pending', 'woocommerce.com', '2026-04-24 04:53:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(140, 'klaviyo_q2_2026', 'marketing', 'en_US', 'Attn Woo: Klaviyo Customer Hub is here', 'Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.', '{}', 'pending', 'woocommerce.com', '2026-04-30 04:53:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(141, 'existing_square_discountcodes_gtm_q2_2026', 'marketing', 'en_US', 'Automatic coupon sync now available in Square', 'The discount codes you create in your Square dashboard will now work directly on your WooCommerce checkout — no need to manually sync coupons. Manage all of your discounts from one place with automatic redemption count updates.', '{}', 'pending', 'woocommerce.com', '2026-05-15 06:53:22', NULL, 0, 'plain', '', 0, 0, 'info'),
(142, 'prospects_square_discountcodes_gtm_q2_2026', 'marketing', 'en_US', 'Square now offers automatic coupon sync', 'Big news for smoother cross-channel sales: you can now create discount codes in Square and have them work directly at checkout on your Woo store, no manual sync required. Save time when you manage your discounts from one place — and keep your online and in-person sales seamlessly connected.', '{}', 'pending', 'woocommerce.com', '2026-05-19 04:53:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(143, 'paypal_bnpl_mx_promo_Q2_2026', 'marketing', 'en_US', 'Bigger carts, lower fees: enable installments today', 'Merchants using PayPal installments see up to 205% higher average order values. Activate 3-installment payments from your PayPal Business dashboard and get 30% off transaction fees for 90 days. Sign up by October 15, 2026. Limited availability. Terms apply.', '{}', 'pending', 'woocommerce.com', '2026-05-21 04:53:08', NULL, 0, 'plain', '', 0, 0, 'info'),
(144, 'stripe_adaptivepricing_q2_2026', 'marketing', 'en_US', 'Sell internationally with Adaptive Pricing from Stripe', 'Adaptive Pricing is now available in the official Stripe for WooCommerce extension. Show prices in local currency across 150+ countries, lifting cross-border revenue by 17.8%. Shoppers pay exactly what they see at checkout, while you settle in your base currency.', '{}', 'pending', 'woocommerce.com', '2026-05-29 04:53:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(145, 'woo-dotcom-course-2026-06-09', 'marketing', 'en_US', 'Learn how to build your store with WooCommerce', 'In this free course, we\'ll help you set up and run your online store with clear, practical guidance.', '{}', 'pending', 'woocommerce.com', '2026-09-25 11:11:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(146, 'google-for-woocommerce-mapi-update', 'update', 'en_US', 'Action Required by October 12, 2026: Your products will stop showing on Google', 'You need to update Google for WooCommerce to the latest version (3.9.4) to continue syncing your products to Google Merchant Center without issues. The Google for WooCommerce version you have installed uses the legacy Content API which has been deprecated and replaced by the advanced <a href=\"https://support.google.com/merchants/answer/16494522?hl=en\">Google Merchant API</a>.', '{}', 'pending', 'woocommerce.com', '2026-09-25 11:11:41', NULL, 0, 'plain', '', 0, 0, 'info');
