(18606, 81, 'new-woo-brand-announcement-feb4-2025-button', 'Read the blog', 'https://woocommerce.com/posts/introducing-the-new-woo-brand/?utm_source=inbox_note&utm_medium=product&utm_campaign=new-woo-brand-announcement-feb4-2025-button', 'unactioned', '', NULL, NULL),
(19198, 82, 'paypal_bnpl_au_promo_Q1_2025_button', 'Enable “Pay in 4” now', 'https://woocommerce.com/document/woocommerce-paypal-payments/?utm_source=inbox_note&utm_medium=product&utm_campaign=paypal_bnpl_au_promo_Q1_2025_button#pay-later-tab', 'unactioned', '', NULL, NULL),
(19959, 83, 'stripe_stripetax_q1_2025_click', 'Automate my taxes with Stripe', 'https://woocommerce.com/products/stripe-tax/?utm_source=inbox_note&utm_medium=product&utm_campaign=stripe_stripetax_q1_2025_click', 'unactioned', '', NULL, NULL),
